# patch-wheel-addons.ps1  (PC Tires, Nov 7 2026)
# Cart add-ons for wheel orders + single install charge. Edits index.html only.
#  - TPMS sensors: customer must choose Add sensors (+$59.99/wheel) or No sensors
#    before checkout whenever wheels are being installed. Nothing pre-ticked.
#  - Lug nuts: optional checkbox, $4.99/nut x lug count from bolt pattern x wheels.
#  - Tires going onto new wheels no longer get charged install twice: the wheel
#    mount & balance covers them (tire line reads "included with wheel mount").
#  - Accessories flow through the add-on total, so checkout, Stripe charge, HST,
#    order emails, invoice and reader all pick them up. Shop stock, never sent to TDG.
#  - Quotes save/restore the TPMS + lug choices. All-in (final price) quotes add nothing on top.
# Prices live in the TDG block: TPMS_SENSOR and LUG_NUT.
# All-or-nothing: every anchor must match before anything is written. Backup + rollback printed.
$ErrorActionPreference = 'Stop'
$path = Join-Path $PSScriptRoot 'index.html'
$utf8 = New-Object System.Text.UTF8Encoding($false)
$s = [System.IO.File]::ReadAllText($path, $utf8)
$orig = $s
if ($s.Contains('function wheelAccLines')) { Write-Host 'Already applied - nothing to do.' -ForegroundColor Yellow; exit 0 }
